//! `ui/src/generated/settings.ts` and `settings-index.json` (spec 06 §1),
//! written by `cargo test -p mado-settings` like the mado-types bindings and
//! checked for drift the same way.

use serde_json::{Value, json};

use crate::REGISTRY;
use crate::types::Scope;

/// TypeScript: the key union, the value type of each key and the defaults.
pub fn settings_ts() -> String {
    let mut out = String::from(
        "// Generated by mado-settings (cargo test -p mado-settings). Do not edit.\n\n",
    );
    out.push_str("export type SettingKey =\n");
    for def in REGISTRY {
        out.push_str(&format!("  | {:?}\n", def.key));
    }
    out.push_str(";\n\nexport interface SettingValues {\n");
    for def in REGISTRY {
        out.push_str(&format!("  {:?}: {};\n", def.key, def.ty.typescript()));
    }
    out.push_str("}\n\nexport const settingDefaults: SettingValues = {\n");
    for def in REGISTRY {
        out.push_str(&format!("  {:?}: {},\n", def.key, def.default_value()));
    }
    out.push_str("};\n");
    out
}

/// The search index source: one entry per setting the settings page lists.
pub fn search_index() -> Value {
    let entries: Vec<Value> = REGISTRY
        .iter()
        .filter(|d| d.scope != Scope::Site)
        .map(|d| {
            json!({
                "key": d.key,
                "section": d.section.id(),
                "label": d.label,
                "help": d.help,
                "keywords": d.keywords,
                "renderer": d.ty.renderer(),
                "protected": d.opts.protected,
                "feature": d.opts.feature,
                "undoNotice": d.opts.undo_notice,
                "restart": format!("{:?}", d.opts.restart).to_lowercase(),
                "scope": d.scope.as_str(),
                "options": match d.ty { crate::types::SettingType::Enum(o) => json!(o), _ => Value::Null },
            })
        })
        .collect();
    Value::Array(entries)
}

/// The JSON Schema of the settings file `settings.import` reads.
pub fn import_schema() -> Value {
    let props = |scope: Scope| -> serde_json::Map<String, Value> {
        REGISTRY
            .iter()
            .filter(|d| d.scope == scope && !d.opts.protected)
            .map(|d| (d.key.to_owned(), d.ty.json_schema()))
            .collect()
    };
    json!({
        "type": "object",
        "required": ["madoSettings"],
        "properties": {
            "madoSettings": { "const": 1 },
            "app": { "type": "object", "properties": props(Scope::App), "additionalProperties": false },
            "profile": { "type": "object", "properties": props(Scope::Profile), "additionalProperties": false },
        },
    })
}
